def split_fields(text: str) -> list[str]:
    fields = []
    field = ""
    escaping = False
    for character in text:
        if escaping:
            if character != "," and character != "\\":
                raise ValueError("invalid escape")
            field += character
            escaping = False
        elif character == "\\":
            escaping = True
        elif character == ",":
            fields.append(field)
            field = ""
        else:
            field += character
    if escaping:
        raise ValueError("dangling backslash")
    fields.append(field)
    return fields

